#!/usr/bin/env bash
set -Eeuo pipefail
[[ $(id -u) == 0 ]] || { echo RUN_AS_ROOT; exit 1; }
[[ $(df -PB1 /var/www/lbb/releases | awk 'NR==2 { print $4 }') -ge 2147483648 ]] || { echo INSUFFICIENT_DISK; exit 1; }
previous=$(readlink -f /var/www/lbb/current)
[[ -f "$previous/src/components/lbb/home/DropStory.tsx" ]] || { echo SOURCE_NOT_FOUND; exit 1; }
[[ -z $(ss -H -ltn 'sport = :18574') ]] || { echo CANARY_PORT_BUSY; exit 1; }
release=$(mktemp -d /var/www/lbb/releases/home-motion-XXXXXXXX)
unit="lbb-home-check-$(basename "$release")"
state=$(mktemp -d /root/lbb-home-state-XXXXXXXX)
switched=0
rollback() {
  local result=$?
  trap - ERR
  if [[ "$switched" == 1 ]]; then
    ln -s "$previous" "/var/www/lbb/current.rollback.$$"
    mv -Tf "/var/www/lbb/current.rollback.$$" /var/www/lbb/current
    systemctl restart lbb.service
    echo "LBB_HOME_ROLLBACK_OK $previous"
  fi
  systemctl stop "$unit.service" >/dev/null 2>&1 || true
  rm -f "$state/runtime.env"
  if [[ "$(readlink -f /var/www/lbb/current)" != "$release" ]]; then rm -rf -- "$release"; fi
  echo "INSTALL_FAILED status=$result candidate=$release"
  exit "$result"
}
trap rollback ERR
tar -C "$previous" --exclude='./.output' --exclude='./.output-before-*' --exclude='./.*-build-backup-*' --exclude='./.git' -cf - . | tar -C "$release" -xf -
cd "$release"
python3 - "$state" <<'PY_PAYLOAD'
import base64,json,sys,pathlib,subprocess
payload=json.loads(r'''{"patch": "--- a/src/components/lbb/BackendProductQuickView.tsx\n+++ b/src/components/lbb/BackendProductQuickView.tsx\n@@ -34,12 +34,9 @@\n const MAX_QTY = 10;\n \n function fallbackMedia(card: BackendCatalogCard): DecisionMedia[] {\n-  const urls =\n-    card.previewImages.length > 0\n-      ? card.previewImages\n-      : card.primaryImage\n-        ? [card.primaryImage]\n-        : [];\n+  const urls = [...new Set([card.primaryImage, ...card.previewImages])].filter(\n+    (url): url is string => Boolean(url),\n+  );\n   return urls.map((src, index) => ({\n     id: `${card.id}:preview:${index}`,\n     src,\n@@ -89,10 +86,21 @@\n     if (model.media.length === 0) return fallbackMedia(card);\n \n     const selected = mediaForColor(model, colorId);\n-    return [...selected, ...model.media].filter(\n-      (media, index, all) => all.findIndex((candidate) => candidate.id === media.id) === index,\n+    const detail = productQuery.data;\n+    const primary = detail?.primaryImage;\n+    const first =\n+      model.media.find((item) => item.src === primary) ??\n+      model.media.find((item) =>\n+        detail?.media.some((media) => media.publicId === item.id && media.role === \"primary\"),\n+      );\n+    return [\n+      ...(first ? [first] : fallbackMedia(card).slice(0, 1)),\n+      ...selected,\n+      ...model.media,\n+    ].filter(\n+      (media, index, all) => all.findIndex((candidate) => candidate.src === media.src) === index,\n     );\n-  }, [card, colorId, model]);\n+  }, [card, colorId, model, productQuery.data]);\n \n   useEffect(() => {\n     setImg(0);\n@@ -221,7 +229,7 @@\n               const delta = end - touchStart.current;\n               touchStart.current = null;\n               if (Math.abs(delta) < 45) return;\n-              setImage(delta > 0 ? img - 1 : img + 1);\n+              setImage(delta > 0 ? img + 1 : img - 1);\n             }}\n           >\n             {gallery[img] ? (\n@@ -253,7 +261,7 @@\n                   type=\"button\"\n                   onClick={() => setImage(img - 1)}\n                   aria-label=\"تصویر قبلی\"\n-                  className=\"tap-target absolute start-2 top-1/2 hidden -translate-y-1/2 place-items-center rounded-xl bg-obsidian/70 text-bone focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-signal md:grid\"\n+                  className=\"tap-target absolute right-2 top-1/2 hidden -translate-y-1/2 place-items-center rounded-xl bg-obsidian/70 text-bone focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-signal md:grid\"\n                 >\n                   <ChevronRight size={18} aria-hidden=\"true\" />\n                 </button>\n@@ -261,11 +269,14 @@\n                   type=\"button\"\n                   onClick={() => setImage(img + 1)}\n                   aria-label=\"تصویر بعدی\"\n-                  className=\"tap-target absolute end-2 top-1/2 hidden -translate-y-1/2 place-items-center rounded-xl bg-obsidian/70 text-bone focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-signal md:grid\"\n+                  className=\"tap-target absolute left-2 top-1/2 hidden -translate-y-1/2 place-items-center rounded-xl bg-obsidian/70 text-bone focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-signal md:grid\"\n                 >\n                   <ChevronLeft size={18} aria-hidden=\"true\" />\n                 </button>\n-                <div className=\"absolute inset-x-0 bottom-3 flex justify-center gap-1.5 md:bottom-4\">\n+                <div\n+                  dir=\"rtl\"\n+                  className=\"absolute inset-x-0 bottom-3 flex justify-center gap-1.5 md:bottom-4\"\n+                >\n                   {gallery.map((item, index) => (\n                     <button\n                       key={item.id}\n--- a/src/components/lbb/home/HeroNarrative.tsx\n+++ b/src/components/lbb/home/HeroNarrative.tsx\n@@ -1,4 +1,4 @@\n-import { useState } from \"react\";\n+import { useRef, useState } from \"react\";\n import { useIdleAutoplay } from \"@/hooks/use-idle-autoplay\";\n import { Link } from \"@tanstack/react-router\";\n import { ArrowDownLeft, ArrowUpLeft, ChevronLeft, ChevronRight } from \"lucide-react\";\n@@ -55,6 +55,8 @@\n   const move = (delta: number) => {\n     if (items.length > 1) setSelected(items[(index + delta + items.length) % items.length].slug);\n   };\n+  const touchOrigin = useRef<{ x: number; y: number } | null>(null);\n+  const swiped = useRef(false);\n   const { ref: heroCarouselRef } = useIdleAutoplay(() => move(1), 7000, items.length > 1);\n   const heroImage =\n     source === \"live\"\n@@ -227,12 +229,37 @@\n           {heroProduct ? (\n             <div\n               ref={heroCarouselRef}\n-              className=\"absolute bottom-5 right-5 w-[min(360px,calc(100%_-_2.5rem))] md:bottom-8 md:right-8\"\n+              onTouchStart={(event) => {\n+                const touch = event.touches[0];\n+                touchOrigin.current = touch ? { x: touch.clientX, y: touch.clientY } : null;\n+                swiped.current = false;\n+              }}\n+              onTouchCancel={() => {\n+                touchOrigin.current = null;\n+              }}\n+              onTouchEnd={(event) => {\n+                const start = touchOrigin.current;\n+                const end = event.changedTouches[0];\n+                touchOrigin.current = null;\n+                if (!start || !end || items.length < 2) return;\n+                const dx = end.clientX - start.x;\n+                if (Math.abs(dx) < 40 || Math.abs(dx) < 1.25 * Math.abs(end.clientY - start.y))\n+                  return;\n+                swiped.current = true;\n+                move(dx > 0 ? 1 : -1);\n+              }}\n+              onClickCapture={(event) => {\n+                if (!swiped.current) return;\n+                swiped.current = false;\n+                event.preventDefault();\n+                event.stopPropagation();\n+              }}\n+              className=\"absolute touch-pan-y bottom-5 right-5 w-[min(360px,calc(100%_-_2.5rem))] md:bottom-8 md:right-8\"\n             >\n               <Link\n                 to=\"/product/$slug\"\n                 params={{ slug: heroProduct.slug }}\n-                className=\"group grid w-full grid-cols-[64px_minmax(0,1fr)_auto] items-center gap-3 rounded-2xl border border-hairline-strong bg-obsidian/95 p-2 text-bone shadow-overlay backdrop-blur\"\n+                className=\"group grid w-full grid-cols-[64px_minmax(0,1fr)_auto] items-center gap-3 rounded-2xl border border-hairline-strong bg-obsidian/95 p-2 text-bone shadow-overlay backdrop-blur [padding-inline:2.25rem]\"\n               >\n                 {heroProduct.image ? (\n                   <img\n@@ -263,24 +290,24 @@\n                 />\n               </Link>\n               {items.length > 1 && (\n-                <div className=\"absolute -top-10 end-0 flex gap-1\">\n+                <>\n                   <button\n                     type=\"button\"\n                     onClick={() => move(-1)}\n                     aria-label=\"محصول قبلی\"\n-                    className=\"grid h-9 w-9 place-items-center rounded-full bg-obsidian/75 text-bone hover:text-signal\"\n+                    className=\"absolute right-0 top-1/2 grid h-11 w-9 -translate-y-1/2 place-items-center text-bone/75 hover:text-signal\"\n                   >\n-                    <ChevronRight size={15} />\n+                    <ChevronRight size={14} strokeWidth={1.4} />\n                   </button>\n                   <button\n                     type=\"button\"\n                     onClick={() => move(1)}\n                     aria-label=\"محصول بعدی\"\n-                    className=\"grid h-9 w-9 place-items-center rounded-full bg-obsidian/75 text-bone hover:text-signal\"\n+                    className=\"absolute left-0 top-1/2 grid h-11 w-9 -translate-y-1/2 place-items-center text-bone/75 hover:text-signal\"\n                   >\n-                    <ChevronLeft size={15} />\n+                    <ChevronLeft size={14} strokeWidth={1.4} />\n                   </button>\n-                </div>\n+                </>\n               )}\n             </div>\n           ) : null}\n--- a/src/components/lbb/home/TrustStrip.tsx\n+++ b/src/components/lbb/home/TrustStrip.tsx\n@@ -26,19 +26,27 @@\n   return (\n     <section\n       dir=\"rtl\"\n-      className=\"border-t border-hairline bg-obsidian px-[var(--lbb-gutter)] py-8\"\n+      className=\"border-t border-hairline bg-obsidian px-[var(--lbb-gutter)] py-2 md:py-8\"\n       aria-label=\"ویژگی‌های تجربه خرید از LBB\"\n     >\n-      <div className=\"mx-auto grid max-w-[var(--lbb-shell-max)] grid-cols-1 gap-4 md:grid-cols-3 md:divide-x md:divide-x-reverse md:divide-hairline-soft\">\n+      <div className=\"mx-auto grid max-w-[var(--lbb-shell-max)] grid-flow-col auto-cols-fr gap-1 overflow-x-auto md:grid-flow-row md:gap-4 md:grid-cols-3 md:divide-x md:divide-x-reverse md:divide-hairline-soft\">\n         {items.map((item, index) => {\n           const Icon = ICONS[item.icon] ?? CircleHelp;\n           const href = safePublicHref(item.href);\n           const content = (\n             <>\n-              <Icon size={21} className=\"mt-0.5 shrink-0 text-signal\" aria-hidden=\"true\" />\n+              <Icon\n+                size={21}\n+                className=\"mt-0.5 size-4 shrink-0 md:size-[21px] text-signal\"\n+                aria-hidden=\"true\"\n+              />\n               <div>\n-                <p className=\"text-sm font-semibold text-bone\">{item.title}</p>\n-                <p className=\"mt-1 text-xs leading-6 text-metal\">{item.description}</p>\n+                <p className=\"text-center text-[10px] leading-4 font-semibold md:text-start md:text-sm text-bone\">\n+                  {item.title}\n+                </p>\n+                <p className=\"mt-1 hidden text-xs md:block leading-6 text-metal\">\n+                  {item.description}\n+                </p>\n               </div>\n             </>\n           );\n@@ -49,14 +57,14 @@\n               href={href}\n               target={href.startsWith(\"https://\") ? \"_blank\" : undefined}\n               rel={href.startsWith(\"https://\") ? \"noopener noreferrer\" : undefined}\n-              className=\"flex items-start gap-3 px-2 py-2 transition-colors hover:text-signal focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-signal md:px-5\"\n+              className=\"flex min-h-11 min-w-0 flex-col items-center justify-center gap-1 px-1 py-1 md:flex-row md:items-start md:justify-start md:gap-3 md:px-2 md:py-2 transition-colors hover:text-signal focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-signal md:px-5\"\n             >\n               {content}\n             </a>\n           ) : (\n             <div\n               key={`${item.title}-${index}`}\n-              className=\"flex items-start gap-3 px-2 py-2 md:px-5\"\n+              className=\"flex min-h-11 min-w-0 flex-col items-center justify-center gap-1 px-1 py-1 md:flex-row md:items-start md:justify-start md:gap-3 md:px-2 md:py-2 md:px-5\"\n             >\n               {content}\n             </div>\n--- a/src/routes/shop.tsx\n+++ b/src/routes/shop.tsx\n@@ -671,11 +671,7 @@\n             <div className=\"grid overflow-hidden rounded-3xl border border-hairline bg-carbon md:grid-cols-2\">\n               <div className=\"relative h-[340px] min-h-0 overflow-hidden bg-obsidian md:col-start-2 md:row-start-1 md:h-[480px]\">\n                 <img\n-                  src={\n-                    presentation.hero.imageUrl ??\n-                    page.socialImageUrl ??\n-                    homeCategoryImage(\"tshirts\")\n-                  }\n+                  src=\"/brand/lbb-shop-storefront.webp\"\n                   alt=\"ویترین فروشگاه پوشاک LBB\"\n                   fetchPriority=\"high\"\n                   className=\"absolute inset-0 h-full w-full object-cover object-center\"\n", "files": {}}''')
state=pathlib.Path(sys.argv[1])
patch=state/'home.patch'
patch.write_text(payload['patch'])
for name,content in payload['files'].items():
    p=pathlib.Path(name)
    if p.exists() and p.read_text()!=content:
        raise SystemExit('EXISTING_FILE_DIFFERS: '+name)
subprocess.run(['patch','--batch','--forward','--dry-run','-p1','-i',str(patch)],check=True)
subprocess.run(['patch','--batch','--forward','-p1','-i',str(patch)],check=True)
for name,content in payload['files'].items():
    p=pathlib.Path(name);p.parent.mkdir(parents=True,exist_ok=True);p.write_text(content)
pathlib.Path("public/brand/lbb-shop-storefront.webp").write_bytes(base64.b64decode(""))
PY_PAYLOAD
if [[ -d .output ]]; then
  old_output=$(mktemp -d "$release/.home-build-backup-XXXXXXXX")
  mv .output "$old_output/output"
fi
VITE_SITE_URL=https://lbbclo.com VITE_LBB_BACKEND_MODE=live VITE_LBB_API_BASE_URL=https://api.lbbclo.com NITRO_PRESET=node-server npm run build
npm run typecheck
node scripts/test-home-autoplay.cjs
[[ -s .output/server/index.mjs ]]
chown -R lbb:lbb "$release"
chmod 755 "$release"
pid=$(systemctl show lbb.service -p MainPID --value)
python3 - "$pid" "$state/runtime.env" <<'PY_ENV'
import pathlib,sys,re
entries=pathlib.Path('/proc/'+sys.argv[1]+'/environ').read_bytes().split(b'\0')
lines=[]
for entry in entries:
    if b'=' not in entry: continue
    k,v=entry.split(b'=',1)
    key=k.decode()
    if not re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*',key): continue
    if not key.startswith(('VITE_','NITRO_','NODE_','LBB_','API_')): continue
    value=v.decode().replace('\\','\\\\').replace('"','\\"')
    if '\n' in value: raise SystemExit('MULTILINE_RUNTIME_ENV_NOT_SUPPORTED')
    lines.append(key+'="'+value+'"')
lines+=['NODE_ENV=production','HOST=127.0.0.1','PORT=18574','NITRO_HOST=127.0.0.1','NITRO_PORT=18574']
p=pathlib.Path(sys.argv[2]);p.write_text('\n'.join(lines)+'\n');p.chmod(0o600)
PY_ENV
systemd-run --unit="$unit" --property=User=lbb --property=Group=lbb --property="WorkingDirectory=$release" --property="EnvironmentFile=$state/runtime.env" /usr/bin/node "$release/.output/server/index.mjs"
check_home() {
  local port="$1" file="$state/home-$1.html"
  for attempt in $(seq 1 30); do
    if curl --compressed -fsS --connect-timeout 2 --max-time 10 "http://127.0.0.1:$port/" -o "$file" 2>/dev/null && grep -q 'data-compact-collection' "$file" && grep -q 'data-home-product-carousel' "$file"; then return 0; fi
    sleep 1
  done
  return 1
}
check_shop() {
  local port="$1"
  curl --compressed -fsS --max-time 15 "http://127.0.0.1:$port/shop" -o "$state/shop.html"
  grep -q '/brand/lbb-shop-storefront.webp' "$state/shop.html"
  curl -fsS --max-time 10 "http://127.0.0.1:$port/brand/lbb-shop-storefront.webp" -o "$state/shop.webp"
  cmp "$state/shop.webp" public/brand/lbb-shop-storefront.webp
}
check_home 18574 || { journalctl -u "$unit" -n 25 --no-pager; false; }
check_shop 18574
echo LBB_HOME_CANARY_OK
rollback_file="/root/lbb-home-rollback-$(date +%Y%m%d-%H%M%S).sh"
printf '#!/usr/bin/env bash\nset -euo pipefail\nln -s %q /var/www/lbb/current.manual-rollback.$$\nmv -Tf /var/www/lbb/current.manual-rollback.$$ /var/www/lbb/current\nsystemctl restart lbb.service\necho LBB_HOME_MANUAL_ROLLBACK_OK\n' "$previous" > "$rollback_file"
chmod 700 "$rollback_file"
ln -s "$release" "/var/www/lbb/current.home.$$"
switched=1
mv -Tf "/var/www/lbb/current.home.$$" /var/www/lbb/current
systemctl restart lbb.service
check_home 5173
check_shop 5173
prod_pid=$(systemctl show lbb.service -p MainPID --value)
[[ $(readlink -f "/proc/$prod_pid/cwd") == "$release" ]]
systemctl is-active --quiet lbb.service
systemctl stop "$unit.service"
rm -f "$state/runtime.env"
trap - ERR
echo "LBB_HOME_DEPLOY_OK $release"
echo "ROLLBACK_COMMAND=bash $rollback_file"
